import{_ as e,o as i,c as o,a2 as t}from"./chunks/framework.CqpfiAoK.js";const b=JSON.parse('{"title":"Lei de Garantia de Habitação","description":"","frontmatter":{},"headers":[],"relativePath":"pt/0045-住房保障法.md","filePath":"pt/0045-住房保障法.md"}'),r={name:"pt/0045-住房保障法.md"};function d(s,a,n,c,l,u){return i(),o("div",null,[...a[0]||(a[0]=[t('<h1 id="lei-de-garantia-de-habitacao" tabindex="-1">Lei de Garantia de Habitação <a class="header-anchor" href="#lei-de-garantia-de-habitacao" aria-label="Permalink to &quot;Lei de Garantia de Habitação&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Projeto</th><th>Conteúdo</th></tr></thead><tbody><tr><td>Número do documento</td><td>45</td></tr><tr><td>Módulo</td><td>Sistema Jurídico e Estrutura de Governança</td></tr><tr><td>Palavras-chave principais</td><td>Direito de Habitação, Habitação de Garantia, Jurisdição Espacial, Ambiente Habitável, Anti-Especulação</td></tr></tbody></table><h2 id="i-objetivo-legislativo-e-principios-fundamentais" tabindex="-1">I. Objetivo Legislativo e Princípios Fundamentais <a class="header-anchor" href="#i-objetivo-legislativo-e-principios-fundamentais" aria-label="Permalink to &quot;I. Objetivo Legislativo e Princípios Fundamentais&quot;">​</a></h2><p>A 《Lei de Garantia de Habitação》 é uma das cinco leis complementares da civilização simbiótica de âncoras, visando garantir o direito de habitação de todos os seres dentro de Hengyuanzhou, estabelecer um sistema de garantia de habitação justo e sustentável, utilizar a tecnologia de jurisdição espacial para fornecer espaços habitacionais adequados a todas as raças, e prevenir a especulação e a predação no setor habitacional.</p><p>Esta lei estabelece os seguintes princípios fundamentais:</p><table tabindex="0"><thead><tr><th>Princípio</th><th>Conteúdo</th></tr></thead><tbody><tr><td>Princípio da Garantia Habitacional</td><td>Cada ser tem o direito de obter um espaço habitacional adequado, o Estado e a civilização têm a obrigação de garantir as necessidades habitacionais básicas</td></tr><tr><td>Princípio da Prioridade ao Bem Público</td><td>A habitação é antes de tudo uma necessidade básica da vida, não um bem de especulação, a habitação de garantia tem caráter de bem público</td></tr><tr><td>Princípio da Eficiência Espacial</td><td>Utilizar a tecnologia de jurisdição espacial para melhorar a eficiência do uso do espaço e expandir os espaços habitáveis</td></tr><tr><td>Princípio da Adaptação Inter-Racial</td><td>Fornecer espaços habitacionais adaptados às características fisiológicas e aos hábitos de vida das diferentes raças</td></tr><tr><td>Princípio do Ambiente Habitável</td><td>Os espaços habitacionais devem possuir bom ambiente ecológico, infraestrutura básica e serviços públicos</td></tr><tr><td>Princípio Anti-Especulação</td><td>Proibir a especulação com habitação como objeto, impedir que a habitação se torne uma ferramenta de predação de riqueza</td></tr></tbody></table><h2 id="ii-garantia-juridica-do-direito-de-habitacao" tabindex="-1">II. Garantia Jurídica do Direito de Habitação <a class="header-anchor" href="#ii-garantia-juridica-do-direito-de-habitacao" aria-label="Permalink to &quot;II. Garantia Jurídica do Direito de Habitação&quot;">​</a></h2><p>Esta lei estabelece claramente que o direito de habitação é um direito fundamental concedido a cada ser pela Constituição Simbiótica, incluindo especificamente:</p><ol><li><strong>Direito Básico de Habitação</strong>: Cada ser tem o direito de obter um espaço habitacional não inferior ao padrão mínimo, e o padrão mínimo é determinado de acordo com o tamanho corporal e as necessidades de vida da raça.</li><li><strong>Direito de Solicitação de Habitação de Garantia</strong>: Os seres qualificados têm o direito de solicitar habitação de garantia, e as condições de solicitação e os critérios de distribuição são abertos e transparentes.</li><li><strong>Direito à Segurança Habitacional</strong>: Os espaços habitacionais devem atender aos padrões de segurança, e casas perigosas e espaços inadequados para habitação não podem ser alugados ou distribuídos.</li><li><strong>Direito à Estabilidade Habitacional</strong>: Os residentes de habitação de garantia, quando qualificados, desfrutam de um direito de habitação estável e não podem ser expulsos arbitrariamente.</li><li><strong>Direito ao Ambiente Habitacional</strong>: Os residentes têm o direito de obter ar limpo, fontes de água e bom ambiente circundante, e têm o direito de apresentar reclamações sobre a poluição ambiental.</li><li><strong>Direito à Reforma Habitacional</strong>: Os residentes têm o direito de realizar reformas razoáveis no espaço habitacional, desde que não afetem a segurança do edifício e os direitos de terceiros.</li></ol><h2 id="iii-sistema-de-garantia-de-habitacao" tabindex="-1">III. Sistema de Garantia de Habitação <a class="header-anchor" href="#iii-sistema-de-garantia-de-habitacao" aria-label="Permalink to &quot;III. Sistema de Garantia de Habitação&quot;">​</a></h2><p>O sistema de garantia de habitação da civilização simbiótica de âncoras é dividido em três tipos de habitação, cobrindo diferentes níveis de necessidade:</p><table tabindex="0"><thead><tr><th>Tipo</th><th>Nome</th><th>Objeto de Garantia</th><th>Método de Distribuição</th><th>Aluguel/Preço</th></tr></thead><tbody><tr><td>Primeiro tipo</td><td>Habitação de Aluguel Público</td><td>Grupos de baixa renda, cultivadores iniciantes, novos imigrantes</td><td>Sistema de solicitação e revisão, distribuição por fila de espera</td><td>Aluguel simbólico baixo</td></tr><tr><td>Segundo tipo</td><td>Habitação de Propriedade Compartilhada</td><td>Grupos de renda média, cultivadores de nível intermediário</td><td>Sistema de solicitação e revisão, distribuição por sorteio</td><td>Abaixo do preço de mercado, propriedade compartilhada entre indivíduo e Estado</td></tr><tr><td>Terceiro tipo</td><td>Habitação Comercial</td><td>Grupos de alta renda, cultivadores avançados</td><td>Transação de mercado</td><td>Preço de mercado, sujeito a regulamentação</td></tr></tbody></table><p>Além disso, a tecnologia de dobra espacial é utilizada para construir &quot;Áreas Residenciais de Espaço Dobrado&quot;: dentro de um espaço físico limitado, a tecnologia de dobra espacial expande a área habitacional, fornecendo mais espaço habitacional para áreas de alta densidade. As áreas residenciais de espaço dobrado devem passar por avaliação de segurança para garantir a estabilidade espacial.</p><h2 id="iv-adaptacao-habitacional-inter-racial" tabindex="-1">IV. Adaptação Habitacional Inter-Racial <a class="header-anchor" href="#iv-adaptacao-habitacional-inter-racial" aria-label="Permalink to &quot;IV. Adaptação Habitacional Inter-Racial&quot;">​</a></h2><p>Para as necessidades habitacionais especiais das diferentes raças dentro de Hengyuanzhou, esta lei estabelece o sistema de adaptação habitacional inter-racial:</p><ul><li><strong>Raças Aquáticas</strong>: Fornecer espaços habitacionais subaquáticos ou residências anfíbias aquático-terrestres, equipadas com sistema de circulação de água e manutenção da qualidade da água.</li><li><strong>Raças Voadoras</strong>: Fornecer espaços habitacionais em alta altitude ou residências com plataforma de pouso e decolagem, equipadas com gerenciamento de tráfego aéreo.</li><li><strong>Vidas de Energia</strong>: Fornecer espaços habitacionais com concentração de energia adequada, equipados com dispositivo de estabilização de energia.</li><li><strong>Raças Gigantes</strong>: Fornecer espaços habitacionais de grande escala, com estrutura do edifício especialmente reforçada.</li><li><strong>Raças Microscópicas</strong>: Fornecer áreas residenciais microscópicas, equipadas com canais de escala e instalações especiais.</li></ul><p>Os padrões de adaptação habitacional inter-racial são formulados conjuntamente pelo departamento competente de habitação e representantes de cada raça, e atualizados regularmente.</p><h2 id="v-construcao-e-gestao-habitacional" tabindex="-1">V. Construção e Gestão Habitacional <a class="header-anchor" href="#v-construcao-e-gestao-habitacional" aria-label="Permalink to &quot;V. Construção e Gestão Habitacional&quot;">​</a></h2><ul><li><strong>Planejamento da Construção Habitacional</strong>: O Estado formula o planejamento da construção habitacional de acordo com o crescimento populacional e a situação de imigração, garantindo o equilíbrio entre oferta e demanda de habitação.</li><li><strong>Padrões de Construção</strong>: A construção de habitação de garantia deve atender aos padrões de segurança, ambientais e de habitabilidade, sendo proibida a redução da qualidade da construção.</li><li><strong>Gestão de Propriedade</strong>: As áreas residenciais adotam um modelo que combina gestão autônoma e gestão profissional de propriedade, e os residentes têm o direito de participar das decisões de gestão de propriedade.</li><li><strong>Manutenção Habitacional</strong>: A manutenção da habitação de garantia é de responsabilidade da instituição de gestão habitacional, e os fundos de manutenção são arcados pela acumulação pública.</li><li><strong>Mecanismo de Saída</strong>: Quando a renda ou o nível de cultivo dos residentes de habitação de garantia excede o padrão de garantia, eles devem sair da habitação de garantia ou convertê-la em habitação comercial, recebendo um período de transição razoável.</li></ul><h2 id="vi-anti-especulacao-e-supervisao" tabindex="-1">VI. Anti-Especulação e Supervisão <a class="header-anchor" href="#vi-anti-especulacao-e-supervisao" aria-label="Permalink to &quot;VI. Anti-Especulação e Supervisão&quot;">​</a></h2><p>Para prevenir a especulação e a predação no setor habitacional, esta lei estabelece as seguintes medidas de supervisão:</p><ol><li>Limitar o número de habitações comerciais que um indivíduo pode possuir, e cobrar imposto predial progressivo sobre o excesso.</li><li>Proibir a sublocação e a revenda de habitação de garantia, e os infratores terão sua qualificação de garantia cancelada e a habitação recuperada.</li><li>Estabelecer um sistema de publicidade de informações sobre transações habitacionais, para evitar operações em caixa-preta e manipulação de preços.</li><li>Implementar gestão de qualificação e supervisão de fundos para desenvolvedores imobiliários, para evitar construções inacabadas e fraudes.</li><li>Estabelecer um mecanismo de reclamações habitacionais e resolução de disputas, para garantir os direitos legais dos residentes.</li></ol><h2 id="vii-responsabilidade-juridica" tabindex="-1">VII. Responsabilidade Jurídica <a class="header-anchor" href="#vii-responsabilidade-juridica" aria-label="Permalink to &quot;VII. Responsabilidade Jurídica&quot;">​</a></h2><p>Atividades que violam as disposições desta lei assumem as seguintes responsabilidades de acordo com a gravidade da infração:</p><ul><li>Distribuir habitação de garantia em violação às regras, ordenar a correção e aplicar punição ao responsável.</li><li>Sublocar ou revender habitação de garantia, cancelar a qualificação de garantia, recuperar a habitação e impor multa.</li><li>Desenvolvedores que reduzem a qualidade da construção, ordenar a reconstrução e impor multa, em casos graves revogar a qualificação.</li><li>Especulação habitacional, cobrar imposto de especulação elevado e impor multa.</li><li>Alugar casas perigosas causando danos aos residentes, assumir responsabilidade por indenização, em casos graves追究 responsabilidade criminal.</li></ul><h2 id="conclusao" tabindex="-1">Conclusão <a class="header-anchor" href="#conclusao" aria-label="Permalink to &quot;Conclusão&quot;">​</a></h2><p>A 《Lei de Garantia de Habitação》 é a implementação do conceito de &quot;todos têm um caminho&quot; da civilização simbiótica de âncoras no setor habitacional. Ao estabelecer um sistema classificado de garantia de habitação, utilizar a tecnologia de jurisdição espacial para expandir os espaços habitacionais, adaptar-se às necessidades habitacionais inter-raciais e combater a especulação habitacional, ela garante que cada ser possa ter uma casa segura, adequada e estável, fornecendo garantia de moradia para o progresso comum de todas as raças.</p><h2 id="documentos-relacionados" tabindex="-1">Documentos relacionados <a class="header-anchor" href="#documentos-relacionados" aria-label="Permalink to &quot;Documentos relacionados&quot;">​</a></h2><ul><li>40-共生宪法总纲 (Princípios Gerais da Constituição Simbiótica)</li><li>39-住房与环境保障 (Garantia de Habitação e Ambiente)</li><li>13-空间法理调度体系详解 (Explicação Detalhada do Sistema de Jurisdição Espacial)</li><li>46-环境保护法 (Lei de Proteção Ambiental)</li></ul>',29)])])}const m=e(r,[["render",d]]);export{b as __pageData,m as default};
